class BoundedBlockingQueue {
    private final Deque<Integer> items = new ArrayDeque<>();
    private final int capacity;

    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notFull  = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();

    public BoundedBlockingQueue(int capacity) { this.capacity = capacity; }

    public void enqueue(int element) throws InterruptedException {
        lock.lock();
        try {
            // while, NOT if. See below — this is the whole question.
            while (items.size() == capacity) notFull.await();
            items.addLast(element);
            notEmpty.signal();          // wake ONE consumer
        } finally {
            lock.unlock();              // finally, or an exception wedges the queue
        }
    }

    public int dequeue() throws InterruptedException {
        lock.lock();
        try {
            while (items.isEmpty()) notEmpty.await();
            int value = items.removeFirst();
            notFull.signal();           // wake ONE producer
            return value;
        } finally {
            lock.unlock();
        }
    }

    public int size() {
        lock.lock();
        try {
            return items.size();
        } finally {
            lock.unlock();
        }
    }
}

