// Timeline that breaks it:
//   T1 producer: queue full, calls await(), releases the lock
//   T2 consumer: dequeues, calls notFull.signal(), releases the lock
//   T3 producer: (was never blocked) takes the lock, enqueues, queue full again
//   T1 producer: wakes, reacquires the lock, does NOT re-check, enqueues
//                -> size is now capacity + 1

public synchronized void enqueue(int element) throws InterruptedException {
    while (items.size() == capacity) wait();   // one wait set for everyone
    items.addLast(element);
    notifyAll();   // MUST be notifyAll: one wait set means notify() can wake
                   // another producer, which re-blocks, and nobody makes progress
}

public synchronized int dequeue() throws InterruptedException {
    while (items.isEmpty()) wait();
    int value = items.removeFirst();
    notifyAll();
    return value;
}

private final Semaphore slots;    // = capacity
private final Semaphore filled;   // = 0
private final ReentrantLock mutex = new ReentrantLock();

public void enqueue(int element) throws InterruptedException {
    slots.acquire();                       // blocks while full
    mutex.lock();
    try { items.addLast(element); } finally { mutex.unlock(); }
    filled.release();
}

public int dequeue() throws InterruptedException {
    filled.acquire();                      // blocks while empty
    mutex.lock();
    try { return items.removeFirst(); } finally { mutex.unlock(); }
}
